import itertools
F={}
tf={'1':np.ones_like(t),'t':t,'t2':t**2,'exp-t':np.exp(-t),'sin':np.sin(t),'cos':np.cos(t),'logt':np.log(t),'sqrtt':np.sqrt(t),'expt':np.exp(t/5)}
for p in [-2,-1,0,1,2,3]:
  for n,v in tf.items():
    F[f'P^{p}*{n}']=P**p*v
ks=list(F); M=np.column_stack([F[k] for k in ks]); y=dP_dt
best=[]
for m in [3]:
  for combo in itertools.combinations(range(len(ks)),m):
    A=M[:,combo]
    c=np.linalg.lstsq(A,y,rcond=None)[0]
    e=np.mean((y-A@c)**2)/np.var(y)
    best.append((e,[ks[i] for i in combo],np.round(c,4)))
best.sort(key=lambda x:x[0])
